  width: 100%;
  padding: 0.75rem 1rem;
  background: #dc2626;
  color: white;
  border: none;
  font-size: 0.95rem;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.2s ease;
}

.delete-btn:hover {
  background: #b91c1c;
}

.delete-btn:focus {
  outline: 2px solid #ef4444;
  outline-offset: 2px;
}

.delete-btn:active {
  background: #991b1b;
}

/* Modal Dialog */
dialog {
  border: none;
  border-radius: 12px;
  background: #1e293b;
  color: #e2e8f0;
  padding: 0;
  max-width: 90vw;
  width: 400px;
  box-shadow: 0 25px 50px rgba(0, 0, 0, 0.5);
}

dialog::backdrop {
  background: rgba(0, 0, 0, 0.6);
  backdrop-filter: blur(2px);
}

.dialog-content {
  padding: 2rem;
}

#delete-heading {
  font-size: 1.5rem;
  margin-bottom: 1rem;
  color: #f1f5f9;
}

#delete-description {
  color: #cbd5e1;
  margin-bottom: 2rem;
  line-height: 1.6;
}

.dialog-actions {
  display: flex;
  gap: 1rem;
  justify-content: flex-end;
}

.dialog-actions button {
  padding: 0.75rem 1.5rem;
  border: none;
  border-radius: 6px;
  font-size: 0.95rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s ease;
}

.btn-cancel {
  background: #475569;
  color: #f1f5f9;
}

.btn-cancel:hover {
  background: #64748b;
}

.btn-cancel:focus {
  outline: 2px solid #94a3b8;
  outline-offset: 2px;
}

.btn-cancel:active {
  background: #334155;
}

.btn-delete {
  background: #dc2626;
  color: white;
}

.btn-delete:hover {
  background: #b91c1c;
}

.btn-delete:focus {
  outline: 2px solid #ef4444;
  outline-offset: 2px;
}

.btn-delete:active {
  background: #991b1b;
}

/* Ensure dialog is hidden when closed */
dialog:not([open]) {
  display: none;
}

/* Responsive */
@media (max-width: 640px) {
  main {
    padding: 1rem;
  }

  h1 {
    font-size: 1.5rem;
    margin-bottom: 1.5rem;
  }

  .gallery-container {
    grid-template-columns: 1fr;
    gap: 1.5rem;
  }

  dialog {
    width: 90vw;
    max-width: 500px;
  }

  .dialog-content {
    padding: 1.5rem;
  }

