    border: 2px solid CanvasText;
  }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  .image-item,
  .delete-btn,
  .btn-cancel,
  .btn-delete,
  dialog::backdrop {
    transition: none;
  }
}
